const fs = require('node:fs');
const vm = require('node:vm');
const assert = require('node:assert/strict');
const root = require('node:path').join(__dirname, '..');
const source = fs.readFileSync(require('node:path').join(root, 'src/game.js'), 'utf8');
const runtime = fs.readFileSync(require('node:path').join(root, 'src/runtime.js'), 'utf8');
const blackboxSource = fs.readFileSync(require('node:path').join(root, 'src/blackbox.js'), 'utf8');
const arcadeSource = fs.readFileSync(require('node:path').join(root, 'src/arcade.js'), 'utf8');
function boot(savedProfile, storageOverrides) {
  const nodes = new Map(), frames = new Map(), events = {}, windowEvents = {}, timers = new Map(), location={hash:''}; let frameId = 0, timerId = 0, seed=8128;
  const storage = new Map(Object.entries(storageOverrides || {}));
  if(savedProfile && !storage.has('neonDriftProfileV1')) storage.set('neonDriftProfileV1', JSON.stringify(savedProfile));
  const seededMath=Object.create(Math);seededMath.random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
  const ctx = new Proxy({}, {get: (o, k) => o[k] || (() => ({addColorStop(){}}))});
  function node(id) {
    if(nodes.has(id)) return nodes.get(id);
    const classes = new Set();
    const n = {style:{setProperty(){}}, textContent:'', innerHTML:'', listeners:{}, appendChild(){}, remove(){}, setAttribute(){}, addEventListener(name,fn){this.listeners[name]=fn;},
      classList:{add(...keys){keys.forEach(k=>classes.add(k));}, remove(...keys){keys.forEach(k=>classes.delete(k));}, contains:k=>classes.has(k), toggle(k,v){if(v===undefined)v=!classes.has(k);v?classes.add(k):classes.delete(k);}},
      querySelectorAll:()=>[node({}),node({})], getContext:()=>ctx, getBoundingClientRect:()=>({width:360,height:540,left:0,top:0})};
    nodes.set(id,n); return n;
  }
  const panelNodes=['bridge','armory','routes','codex','archive','guides','workbench','protocols','challenges','signals','salvage','lab','blackbox','dispatch','chronicle'].map(name=>{const panel=node('panel-'+name);panel.dataset={hubPanel:name};return panel;});
  const document={hidden:false,getElementById:node,createElement:()=>node({}),querySelectorAll:selector=>selector==='[data-hub-panel]'?panelNodes:[],addEventListener:(name,fn)=>{events[name]=fn;}};
  const sandbox={document,
    window:{devicePixelRatio:1,location,history:{pushState(_state,_title,url){location.hash=url.slice(url.indexOf('#'));}},addEventListener:(name,fn)=>{windowEvents[name]=fn;},setInterval:fn=>{const id=++timerId;timers.set(id,fn);return id;},clearInterval:id=>timers.delete(id),setTimeout:fn=>{const id=++timerId;timers.set(id,fn);return id;},clearTimeout:id=>timers.delete(id)},navigator:{},localStorage:{getItem:key=>storage.has(key)?storage.get(key):null,setItem:(key,value)=>storage.set(key,String(value)),removeItem:key=>storage.delete(key)},
    Image:class{},performance:{now:()=>0},setTimeout:()=>1,clearTimeout(){},
    requestAnimationFrame:fn=>{frames.set(++frameId,fn);return frameId;},cancelAnimationFrame:id=>frames.delete(id),console,Math:seededMath};
  vm.createContext(sandbox);
  for(const file of ['catalog','core'])vm.runInContext(fs.readFileSync(require('node:path').join(root,'src',file+'.js'),'utf8'),sandbox);
  vm.runInContext(runtime,sandbox);
  vm.runInContext(blackboxSource,sandbox);
  vm.runInContext(arcadeSource,sandbox);
  vm.runInContext(source.replace(/\}\)\(\);\s*$/, 'globalThis.probe={run:function(code){return eval(code);}};})();'),sandbox);
  sandbox.probe.run('soundOn=false;startGame();ship.crit=0');
  return {run:s=>sandbox.probe.run(s),frames,events,windowEvents,document,nodes,panels:panelNodes,location,storage,runTimer:id=>{const fn=timers.get(id);if(fn)fn();}};
}
let failed=0;
function test(name, fn, savedProfile, storageOverrides){try{fn(boot(savedProfile,storageOverrides));console.log('PASS',name);}catch(e){failed++;console.log('FAIL',name, e.message);}}
test('v5 archive upgrades without losing commander progress',t=>{assert.equal(t.run('profile.schemaVersion'),11);assert.equal(t.run('profile.runs'),7);assert.equal(t.run('profile.shards'),42);assert.equal(t.run('profile.relayBest'),180);assert.equal(t.run('profile.blackboxRuns'),0);assert.equal(t.run('profile.blackboxClears'),0);assert.equal(t.run('profile.borderTactics.runs'),0);assert.equal(t.run("profile.arcadeMastery.relay"),null);},{schemaVersion:5,runs:7,shards:42,relayBest:180,station:{intel:3,modules:2,research:1,claimed:{}}});
test('new run fires bullets',t=>{t.run('update(.016)');assert.ok(t.run('bullets.length')>0);});
test('overdrive charges from combat and stays inert before ready',t=>{t.run("resetRun();g.running=true;enemies=[];spawnEnemy();var enemy=enemies[0];enemy.hp=1;damageEnemy(enemy,999,{slow:false});");const charged=t.run('g.overdrive');assert.ok(charged>0&&charged<100);const bulletsBefore=t.run('enemyBullets.length');assert.equal(t.run('useOverdrive()'),false);assert.equal(t.run('g.overdrive'),charged);assert.equal(t.run('enemyBullets.length'),bulletsBefore);});
test('overdrive clears threats and grants a short fire window',t=>{t.run("resetRun();g.running=true;g.overdrive=100;enemyBullets=[{x:20,y:20,vx:0,vy:0,r:4,damage:4,life:8}];lasers=[{x:180,y:120,angle:0,length:400,width:12,life:1,delay:0,hitTimer:0,damage:4}];enemies=[];spawnEnemy();useOverdrive();");assert.equal(t.run('g.overdrive'),0);assert.equal(t.run('enemyBullets.length'),0);assert.equal(t.run('lasers.length'),0);assert.ok(t.run('ship.hasteTimer>=4.8'));});
test('starting a run removes the command deck overlay',t=>{t.run('resetRun()');assert.equal(t.run("ui.hubOverlay.classList.contains('hidden')"),false);t.run('startGame()');assert.equal(t.run("ui.hubOverlay.classList.contains('hidden')"),true);});
test('player has finite collision radius',t=>assert.ok(t.run('Number.isFinite(ship.r)&&ship.r>0')));
test('touch control keeps ship above the finger',t=>{t.run('targetPos(180,300,true)');assert.equal(t.run('ship.targetY'),248);});
test('drag direction changes the real main-fire angle',t=>{t.run("resetRun();ship.x=180;ship.y=420;targetPos(300,260,true);bullets=[];ship.fireTimer=0;shoot()");assert.ok(t.run('bullets[0].vx>0'));assert.ok(t.run('bullets[0].vy<0'));});
test('each combat wave exposes a tactical contract and marked target',t=>{t.run("resetRun();g.wave=2;g.running=true;updateWaveMod();enemies=[];spawnEnemy();killEnemy(enemies[0])");assert.equal(t.run('g.contract.id'),'hunt');assert.equal(t.run('g.contract.complete'),true);assert.ok(t.run('g.score>=460'));});
test('hunt contracts retarget after a marked enemy disappears',t=>{t.run("resetRun();g.wave=2;g.running=true;updateWaveMod();enemies=[];spawnEnemy();spawnEnemy();var old=g.contract.targetUid;enemies=enemies.filter(function(e){return e.uid!==old;});ensureHuntTarget()");assert.ok(t.run('g.contract.targetUid'));assert.equal(t.run('enemies.some(function(e){return e.uid===g.contract.targetUid&&e.marked;})'),true);});
test('boss wave contracts require one shield break and grant a behavior window',t=>{t.run("resetRun();g.wave=5;g.running=true;updateWaveMod();completeWaveContract('break')");assert.equal(t.run('g.contract.target'),1);assert.equal(t.run('g.breakWindow'),3.2);assert.equal(t.run('g.contract.complete'),true);});
test('enemy projectile damages player',t=>{t.run('ship.shield=0;ship.regen=0;enemyBullets.push({x:ship.x,y:ship.y,vx:0,vy:0,r:4,damage:20,life:8});update(.016)');assert.ok(t.run('ship.hp<ship.maxHp'));});
test('enemy breach creates real pressure instead of disappearing at the edge',t=>{
  const result=JSON.parse(t.run("(function(){resetRun();g.running=true;g.wave=4;g.routeMod={speed:1};ship.shield=0;var before=ship.hp;var e={uid:'breach-test',type:'scout',boss:false,contact:18,dead:false};var used=breachEnemy(e);return JSON.stringify({used:used,dead:e.dead,damage:before-ship.hp,breaches:g.breaches,waveBreaches:g.waveBreaches,combo:g.combo,score:g.score});})()"));
  assert.equal(result.used,true);assert.equal(result.dead,true);assert.ok(result.damage>=4);assert.equal(result.breaches,1);assert.equal(result.waveBreaches,1);assert.equal(result.combo,0);assert.ok(result.score<0||result.score===0);
});
test('repair pickup is collected',t=>{t.run("ship.hp=40;drops.push({type:'heal',x:ship.x,y:ship.y,r:9,vy:0,life:5});update(.016)");assert.equal(t.run('drops.length'),0);});
test('loot replaces correct slot',t=>{t.run("equipNewItem(makeItem('phase'))");assert.equal(t.run('g.equipment.weapon.defId'),'phase');assert.equal(t.run('Object.keys(g.equipment).length'),5);});
test('route selection updates the active route',t=>{t.run("selectRoute('abyss')");assert.equal(t.run("profile.selectedRoute"),'abyss');assert.equal(t.run("g.route.id"),'abyss');});
test('seeded route planner is stable and selectable',t=>{const first=JSON.parse(t.run("(function(){profile.pendingSeed='ND-TEST-01';profile.routePlan=null;var map=ensureRoutePlan();return JSON.stringify({seed:map.seed,stages:map.stages.length,ids:profile.routePlan.ids.slice(),boss:map.stages[4].nodes[0].type});})()"));assert.equal(first.stages,5);assert.equal(first.boss,'boss');t.run("selectRouteNode(1,ensureRoutePlan().stages[1].nodes[ensureRoutePlan().stages[1].nodes.length-1].id)");const second=JSON.parse(t.run('JSON.stringify({seed:profile.routePlan.seed,ids:profile.routePlan.ids.slice()})'));assert.equal(second.seed,'ND-TEST-01');assert.notDeepEqual(second.ids,first.ids);});
test('starting a run carries a seed and route node modifiers into combat',t=>{t.run("profile.pendingSeed='ND-TEST-02';profile.routePlan=null;startGame();g.running=true;updateWaveMod()");assert.equal(t.run('g.runSeed'),'ND-TEST-02');assert.ok(t.run('g.routeMap.stages.length')===5);assert.ok(t.run('Number.isFinite(g.nodeRewardMultiplier)'));});
test('selected route nodes change later wave pressure',t=>{t.run("profile.pendingSeed='ND-TEST-03';profile.routePlan=null;var map=ensureRoutePlan();var salvage=map.stages[1].nodes.find(function(node){return node.type==='salvage';});if(!salvage)salvage=map.stages[1].nodes[0];selectRouteNode(1,salvage.id);startGame();g.running=true;g.wave=3;updateWaveMod();spawnEnemy()");assert.ok(t.run('g.nodeMod.hp>=1'));});
test('protocol upgrade persists and changes the next run baseline',t=>{const before=t.run('ship.maxHp');t.run('profile.shards=20;buyProtocol(\'hull\')');assert.equal(t.run("profile.protocols.hull"),1);assert.equal(t.run('profile.shards'),14);assert.equal(t.run('ship.maxHp'),before+8);});
test('wave three opens a single route event and choice resumes combat',t=>{t.run('g.wave=2;g.waveKills=g.waveTarget;enemies=[];advanceWave()');assert.equal(t.run('g.wave'),3);assert.equal(t.run('g.eventActive'),true);assert.equal(t.run("ui.eventOverlay.classList.contains('hidden')"),false);t.run("chooseEvent(eventForWave(),eventForWave().choices[1])");assert.equal(t.run('g.eventActive'),false);assert.equal(t.run("ui.eventOverlay.classList.contains('hidden')"),true);assert.equal(t.run('g.scrap'),8);});
test('event repair clears route hazards',t=>{t.run('g.wave=2;g.waveKills=g.waveTarget;enemies=[];advanceWave();g.eventHazard=1.24;g.eventSlow=.82;chooseEvent(eventForWave(),eventForWave().choices[0])');assert.equal(t.run('g.eventHazard'),1);assert.equal(t.run('g.eventSlow'),1);});
test('desktop number shortcut selects an event choice',t=>{t.run('g.wave=2;g.waveKills=g.waveTarget;enemies=[];advanceWave();ui.eventChoices.querySelectorAll=function(){return[{click:function(){}},{click:function(){chooseEvent(eventForWave(),eventForWave().choices[1]);}}]};');t.windowEvents.keydown({code:'Digit2',key:'2',repeat:false,preventDefault(){}});assert.equal(t.run('g.eventActive'),false);assert.equal(t.run('g.scrap'),8);});
test('signal relay records a completed session',t=>{t.run('startRelay();relay.score=42;relay.hits=3;finishRelay()');assert.equal(t.run('relay.running'),false);assert.equal(t.run('profile.relayBest'),42);assert.equal(t.run('profile.relayRuns'),1);assert.equal(t.run('profile.relayHits'),3);});
test('signal relay separates caches from decoy pulses and stages the run',t=>{const result=JSON.parse(t.run("(function(){startRelay();clearRelayTarget();Math.random=function(){return .99;};spawnRelayTarget();relay.target.listeners.click();var missed=relay.misses,streak=relay.streak;Math.random=function(){return 0;};clearRelayTarget();spawnRelayTarget();relay.target.listeners.click();return JSON.stringify({missed:missed,streak:streak,stage:relay.stage,hits:relay.hits,caches:relay.caches,score:relay.score});})()"));assert.equal(result.missed,1);assert.equal(result.streak,0);assert.equal(result.stage,1);assert.equal(result.hits,1);assert.equal(result.caches,1);assert.ok(result.score>0);});
test('echo lab records a solved session',t=>{t.run('startLab();lab.round=4;lab.score=73;lab.solved=4;finishLab("sequence")');assert.equal(t.run('lab.running'),false);assert.equal(t.run('profile.labBest'),73);assert.equal(t.run('profile.labRuns'),1);assert.equal(t.run('profile.labSolved'),4);assert.equal(t.run("profile.history[0].type"),'lab');});
test('echo run shuffles rule order and protects against invalid node input',t=>{const result=JSON.parse(t.run("(function(){startLab();lab.round=0;lab.ruleOrder=['reverse','forward','split','shift'];beginLabRound();var reverse=lab.rule==='reverse'&&lab.inputSequence[0]===lab.sequence[lab.sequence.length-1];lab.phase='input';var wrong=(lab.inputSequence[0]+1)%9;handleLabNode(wrong);return JSON.stringify({reverse:reverse,lives:lab.lives,running:lab.running,phase:lab.phase,mistakes:lab.mistakes});})()"));assert.equal(result.reverse,true);assert.equal(result.lives,2);assert.equal(result.running,true);assert.equal(result.phase,'memorize');assert.equal(result.mistakes,1);});
test('echo lab drafts a protocol after every three solved rounds',t=>{t.run("startLab();lab.round=2;lab.solved=2;lab.ruleOrder=['forward','reverse','split','shift'];beginLabRound();lab.sequence=[2];lab.inputSequence=[2];lab.displaySequence=[{index:2,decoy:false}];lab.phase='input';lab.inputIndex=0;handleLabNode(2)");assert.equal(t.run('lab.running'),true);assert.equal(t.run("lab.phase"),'draft');assert.equal(t.run('lab.offers.length'),3);t.run("chooseLabPerk(lab.offers[0].id)");assert.notEqual(t.run("lab.phase"),'draft');});
