test('short mode runtimes release every timer on exit',t=>{const result=JSON.parse(t.run("(function(){startRelay();var relayLive=relayRuntime.activeCount();finishRelay();var relayClear=relayRuntime.activeCount();startLab();var labLive=labRuntime.activeCount();stopLab(true);var labClear=labRuntime.activeCount();startSalvage();var salvageLive=salvageRuntime.activeCount();setHubView('bridge');return JSON.stringify({relayLive:relayLive,relayClear:relayClear,labLive:labLive,labClear:labClear,salvageLive:salvageLive,allClear:relayRuntime.activeCount()+labRuntime.activeCount()+salvageRuntime.activeCount()});})()"));assert.ok(result.relayLive>0);assert.equal(result.relayClear,0);assert.ok(result.labLive>0);assert.equal(result.labClear,0);assert.ok(result.salvageLive>0);assert.equal(result.allClear,0);});
