test('salvage only accepts adjacent unrevealed cells once',t=>{const result=JSON.parse(t.run("(function(){startSalvage();salvage.board=Array.from({length:25},function(){return {type:'empty',revealed:false};});salvage.board[12]={type:'start',revealed:true};salvage.board[7]={type:'scrap',revealed:false};salvage.player=12;salvage.revealed=[12];salvage.score=0;salvage.collected=0;salvage.phase='explore';salvage.running=true;handleSalvageCell(0);var blocked={player:salvage.player,score:salvage.score,collected:salvage.collected};handleSalvageCell(7);var first={player:salvage.player,score:salvage.score,collected:salvage.collected};handleSalvageCell(7);return JSON.stringify({blocked:blocked,first:first,after:{player:salvage.player,score:salvage.score,collected:salvage.collected}});})()"));assert.equal(result.blocked.player,12);assert.equal(result.first.collected,1);assert.equal(result.after.collected,1);});
