test('salvage beacon offers extraction or a riskier next deck',t=>{const result=JSON.parse(t.run("(function(){startSalvage();salvage.phase='decision';salvage.collected=3;salvage.timeLeft=30;var before=salvage.score;var descended=descendSalvage();return JSON.stringify({descended:descended,sector:salvage.sector,phase:salvage.phase,time:salvage.timeLeft,hazards:salvage.board.filter(function(cell){return cell.type==='hazard';}).length,scoreGain:salvage.score-before});})()"));assert.equal(result.descended,true);assert.equal(result.sector,2);assert.equal(result.phase,'explore');assert.ok(result.time<60);assert.ok(result.hazards>=4);assert.ok(result.scoreGain>=0);});
