test('mastery choices lock during play and unlock again after stopping',t=>{t.run("profile.relayHits=12;selectArcadeMastery('relay','wideband');startRelay()");assert.equal(t.run('relay.windowBonus'),320);assert.equal(t.run('relay.masteryId'),'wideband');assert.equal(t.run("selectArcadeMastery('relay',null)"),false);assert.equal(t.run("profile.arcadeMastery.relay"),'wideband');assert.ok(t.run("ui.relayMastery.innerHTML.includes('data-mastery-id=\"wideband\" aria-pressed=\"true\" disabled')"));t.run('stopRelay(true)');assert.ok(t.run("ui.relayMastery.innerHTML.includes('data-mastery-id=\"wideband\" aria-pressed=\"true\" disabled')")===false);t.run("profile.relayHits=40;selectArcadeMastery('relay','cache');startRelay()");assert.equal(t.run('relay.cacheBonus'),.08);});
test('each short game locks its equipped mastery for the active run',t=>{t.run("profile.relayHits=12;profile.labSolved=9;profile.salvageCollected=6;profile.blackboxLocks=4;selectArcadeMastery('relay','wideband');startRelay()");assert.ok(t.run("ui.relayMastery.innerHTML.includes('data-mastery-id=\"wideband\" aria-pressed=\"true\" disabled')"));t.run('stopRelay(true);selectArcadeMastery(\'lab\',\'slowflash\');startLab()');assert.ok(t.run("ui.labMastery.innerHTML.includes('data-mastery-id=\"slowflash\" aria-pressed=\"true\" disabled')"));t.run('stopLab(true);selectArcadeMastery(\'salvage\',\'hull\');startSalvage()');assert.ok(t.run("ui.salvageMastery.innerHTML.includes('data-mastery-id=\"hull\" aria-pressed=\"true\" disabled')"));t.run('stopSalvage(true);selectArcadeMastery(\'blackbox\',\'budget\');startBlackbox()');assert.ok(t.run("ui.blackboxMastery.innerHTML.includes('data-mastery-id=\"budget\" aria-pressed=\"true\" disabled')"));});
test('echo mastery changes memory flash and starting lives',t=>{t.run("profile.labSolved=9;selectArcadeMastery('lab','slowflash');startLab()");assert.equal(t.run('lab.flashBonus'),100);t.run("stopLab(true);profile.labSolved=28;selectArcadeMastery('lab','extraheart');startLab()");assert.equal(t.run('lab.lives'),4);});
test('salvage mastery absorbs one hazard or adds oxygen per deck',t=>{t.run("profile.salvageCollected=6;selectArcadeMastery('salvage','hull');startSalvage();salvage.board=Array.from({length:25},function(){return {type:'empty',revealed:false};});salvage.board[12]={type:'start',revealed:true};salvage.board[7]={type:'hazard',revealed:false};salvage.player=12;salvage.revealed=[12];salvage.phase='explore';salvage.timeLeft=45;handleSalvageCell(7)");assert.equal(t.run('salvage.timeLeft'),45);assert.equal(t.run('salvage.heat'),1);assert.equal(t.run('salvage.masteryGuard'),0);t.run("stopSalvage(true);profile.salvageCollected=20;selectArcadeMastery('salvage','oxygen');startSalvage()");assert.equal(t.run('salvage.timeLeft'),72);t.run("salvage.phase='decision';salvage.collected=3;descendSalvage()");assert.equal(t.run('salvage.timeLeft'),69);});
test('blackbox mastery adds moves or a free hint without score debt',t=>{t.run("profile.blackboxLocks=4;selectArcadeMastery('blackbox','budget');startBlackbox()");assert.equal(t.run('blackbox.movesBonus'),3);assert.equal(t.run('blackbox.board.moveLimit'),t.run("window.NeonBlackbox.generate(1,blackbox.seed,0,0).moveLimit+3"));t.run("stopBlackbox(true);profile.blackboxLocks=15;selectArcadeMastery('blackbox','reader');startBlackbox();hintBlackbox()");assert.equal(t.run('blackbox.hints'),1);assert.equal(t.run('blackbox.freeHints'),0);assert.equal(t.run('blackbox.hintDebt'),0);});
test('game feedback triggers separate mode animations',t=>{t.run("arcadeFeedback('relay','cache');arcadeFeedback('lab','error');arcadeFeedback('salvage','relic');arcadeFeedback('blackbox','rotate')");assert.equal(t.run("ui.relayBoard.classList.contains('fxCache')"),true);assert.equal(t.run("ui.labBoard.classList.contains('fxError')"),true);assert.equal(t.run("ui.salvageBoard.classList.contains('fxRelic')"),true);assert.equal(t.run("ui.blackboxBoard.classList.contains('fxRotate')"),true);});
test('loadout presets round-trip rarity and level',t=>{t.run("resetRun();g.equipment.weapon=makeItem('phase','epic');g.equipment.weapon.level=4;savePreset(0);g.equipment.weapon=makeItem('pulse','common');loadPreset(0)");assert.equal(t.run('g.equipment.weapon.defId'),'phase');assert.equal(t.run('g.equipment.weapon.rarity'),'epic');assert.equal(t.run('g.equipment.weapon.level'),4);assert.equal(t.run('profile.activeLoadout.weapon.defId'),'phase');});
test('legacy four-slot loadouts migrate with a default subweapon',t=>{const result=JSON.parse(t.run("(function(){profile.activeLoadout={weapon:{defId:'pulse',rarity:'common',level:1},core:{defId:'nano',rarity:'common',level:1},utility:{defId:'emp',rarity:'common',level:1},engine:{defId:'drift',rarity:'common',level:1}};resetRun();var value={count:Object.keys(g.equipment).length,subweapon:g.equipment.subweapon.defId};profile.activeLoadout=null;return JSON.stringify(value);})()"));assert.equal(result.count,5);assert.equal(result.subweapon,'missile');});
test('invalid loadout preset is rejected without replacing the build',t=>{t.run("resetRun();var before=g.equipment.weapon.defId;profile.presets[1]={weapon:{defId:'not-real',rarity:'legendary',level:99}};loadPreset(1)");assert.equal(t.run('g.equipment.weapon.defId'),'pulse');});
test('content hub renders authored codex and guide collections',t=>{assert.equal(t.run('codexEntries.length'),9);assert.equal(t.run('guideEntries.length'),11);t.run("contentState.codex='sector';renderHubCodex();contentState.guides='boss';renderHubGuides()");assert.equal(t.run('ui.codexCount.textContent'),'3 条记录');assert.equal(t.run('ui.guideCount.textContent'),'1 篇笔记');});
test('workbench previews a build without mutating the live loadout',t=>{const result=JSON.parse(t.run("(function(){resetRun();var live=g.equipment.weapon.defId;workbenchSetItem('splitter');var planned=workbench.equipment.weapon.defId;var preview=workbenchPreview();return JSON.stringify({live:live,planned:planned,dps:core.weaponDps(preview.stats)});})()"));assert.equal(result.live,'pulse');assert.equal(result.planned,'splitter');assert.ok(result.dps>0);});
test('workbench saves a serializable preset without activating it',t=>{t.run("resetRun();profile.presets=[null,null,null];workbenchSetItem('phase');workbenchCycleRarity(2);workbenchAdjustLevel(2);saveWorkbenchPreset(1)");assert.equal(t.run('profile.presets[1].weapon.defId'),'phase');assert.equal(t.run('profile.presets[1].weapon.level'),3);assert.equal(t.run('profile.activeLoadout'),null);});
test('workbench exposes cross-mode blueprint progress',t=>{t.run("profile.relayHits=12;profile.labSolved=1;profile.salvageCaches=0;renderHubWorkbench()");assert.equal(t.run("ui.workbenchBlueprints.innerHTML.includes('BLUEPRINT PIPELINE')"),true);assert.equal(t.run("ui.workbenchBlueprints.innerHTML.includes('猎蜂无人机')"),true);assert.equal(t.run("ui.workbenchBlueprints.innerHTML.includes('12 / 24 累计命中')"),true);});
test('existing short-mode progress auto-unlocks blueprints on sync',t=>{t.run("profile.relayHits=24;profile.labSolved=3;profile.salvageCaches=2;profile.blueprints=[];syncBlueprintUnlocks(true)");assert.equal(t.run("profile.blueprints.length"),3);assert.equal(t.run("isItemUnlocked(itemDefs.find(function(def){return def.id==='beam';}))"),true);});
test('multi-hop electric branches consume remaining jumps',t=>{const result=JSON.parse(t.run("(function(){resetRun();g.equipment.weapon=makeItem('arc');g.equipment.weapon.branch='storm';recalcBuild(true);enemies=[{uid:'a',x:100,y:100,r:10,hp:100,maxHp:100,shield:0,armor:0,dead:false,type:'scout',typeColor:'#fff'},{uid:'b',x:145,y:100,r:10,hp:100,maxHp:100,shield:0,armor:0,dead:false,type:'scout',typeColor:'#fff'},{uid:'c',x:190,y:100,r:10,hp:100,maxHp:100,shield:0,armor:0,dead:false,type:'scout',typeColor:'#fff'},{uid:'d',x:235,y:100,r:10,hp:100,maxHp:100,shield:0,armor:0,dead:false,type:'scout',typeColor:'#fff'}];var source={chain:true,chainRemaining:traits.chain,hitIds:{a:true}};damageEnemy(enemies[0],20,source);return JSON.stringify({chain:traits.chain,remaining:source.chainRemaining,fx:chainFx.length,hit:Object.keys(source.hitIds).length});})()"));assert.equal(result.chain,3);assert.equal(result.remaining,0);assert.equal(result.fx,3);assert.equal(result.hit,4);});
test('dispatch feed keeps a visible release history',t=>{t.run('renderHubDispatch()');assert.equal(t.run('dispatchEntries.length'),23);assert.equal(t.run('ui.dispatchGrid.innerHTML.includes(\'V19 / PLAYABLE\')'),true);assert.equal(t.run('ui.dispatchHero.innerHTML.includes(\'V50 / BREACH PRESSURE\')'),true);});
test('six game modes open on route-level screens outside the station shell',t=>{t.run('renderArcadeLanding()');assert.equal(t.run('ui.arcadeRunCount.textContent'),'0');assert.equal(t.run('ui.arcadeBorderClears.textContent'),'0');assert.equal(t.run('ui.arcadeRelayBest.textContent'),'0');assert.equal(t.run('ui.arcadeSalvageBest.textContent'),'0');assert.equal(t.run('ui.arcadeBlackboxBest.textContent'),'0');t.run("enterArcadeGame('relay',false)");assert.equal(t.location.hash,'#game/relay');assert.equal(t.run("ui.hubTitle.textContent"),'信号台');assert.equal(t.run("app.classList.contains('arcadeGameMode')"),true);assert.equal(t.run("ui.arcadeGamePages.classList.contains('hidden')"),false);assert.equal(t.run("ui.hubOverlay.classList.contains('hidden')"),true);assert.equal(t.run("ui.expeditionGamePage.classList.contains('hidden')"),true);assert.equal(t.panels.find(p=>p.dataset.hubPanel==='signals').classList.contains('active'),true);assert.equal(t.panels.find(p=>p.dataset.hubPanel==='bridge').classList.contains('active'),false);t.run("enterArcadeGame('expedition',false)");assert.equal(t.location.hash,'#game/expedition');assert.equal(t.run("ui.expeditionGamePage.classList.contains('hidden')"),false);assert.equal(t.run("ui.hubOverlay.classList.contains('hidden')"),true);t.run("enterStation('routes',false)");assert.equal(t.location.hash,'#station/routes');assert.equal(t.run("app.classList.contains('hubMode')"),true);assert.equal(t.run("ui.arcadeGamePages.classList.contains('hidden')"),true);assert.equal(t.panels.find(p=>p.dataset.hubPanel==='routes').classList.contains('active'),true);t.run('openArcadeLanding(true)');assert.equal(t.run("ui.arcadeLanding.classList.contains('hidden')"),false);});
test('browser route restoration returns directly to the requested independent game',t=>{t.location.hash='#game/blackbox';t.windowEvents.hashchange();assert.equal(t.run("app.classList.contains('arcadeGameMode')"),true);assert.equal(t.run("ui.arcadeGamePages.classList.contains('hidden')"),false);assert.equal(t.run("ui.hubTitle.textContent"),'黑盒解码');assert.equal(t.panels.find(p=>p.dataset.hubPanel==='blackbox').classList.contains('active'),true);t.location.hash='#station/codex';t.windowEvents.hashchange();assert.equal(t.run("app.classList.contains('hubMode')"),true);assert.equal(t.run("ui.hubTitle.textContent"),'星区资料库');assert.equal(t.panels.find(p=>p.dataset.hubPanel==='codex').classList.contains('active'),true);});
test('legacy station game bookmarks canonicalize to their independent game routes',t=>{const aliases={signals:'relay',lab:'lab',salvage:'salvage',blackbox:'blackbox',expedition:'expedition',border:'border'};Object.keys(aliases).forEach(alias=>{t.location.hash='#station/'+alias;t.windowEvents.hashchange();assert.equal(t.location.hash,'#game/'+aliases[alias]);assert.equal(t.run("app.classList.contains('arcadeGameMode')"),true);});t.location.hash='#game/bridge';t.windowEvents.hashchange();assert.equal(t.location.hash,'#station/bridge');assert.equal(t.run("app.classList.contains('hubMode')"),true);});
test('malformed profile counters are normalized before settlement',t=>{assert.equal(t.run('profile.shards'),0);assert.equal(t.run('profile.runs'),0);assert.equal(t.run('profile.totalKills'),0);},{schemaVersion:11,shards:'oops',runs:-5,totalKills:'12x',selectedShip:'unknown',selectedRoute:'unknown'});
test('profile storage recovers from a corrupt primary using the last valid backup',t=>{assert.equal(t.run('profile.shards'),27);assert.equal(t.run('profile.runs'),4);assert.ok(t.storage.get('neonDriftProfileV1').includes('neon-drift-profile'));},null, {'neonDriftProfileV1':'{broken','neonDriftProfileV1.backup':JSON.stringify({kind:'neon-drift-profile',schema:1,revision:8,savedAt:1,profile:{schemaVersion:11,shards:27,runs:4}})});
test('profile storage prefers the newest valid pending record after an interrupted write',t=>{assert.equal(t.run('profile.shards'),31);assert.equal(t.run('profile.runs'),6);assert.ok(t.storage.get('neonDriftProfileV1').includes('neon-drift-profile'));},null, {'neonDriftProfileV1':JSON.stringify({kind:'neon-drift-profile',schema:1,revision:2,savedAt:1,profile:{schemaVersion:11,shards:8,runs:1}}),'neonDriftProfileV1.pending':JSON.stringify({kind:'neon-drift-profile',schema:1,revision:3,savedAt:2,profile:{schemaVersion:11,shards:31,runs:6}})});
test('short arcade timers do not consume progress while the document is hidden',t=>{t.run('startRelay();relay.timeLeft=22;document.hidden=true');t.runTimer(t.run('relay.interval'));assert.equal(t.run('relay.timeLeft'),22);t.run('startLab();lab.timeLeft=77;document.hidden=true');t.runTimer(t.run('lab.clock'));assert.equal(t.run('lab.timeLeft'),77);t.run('startSalvage();salvage.timeLeft=44;document.hidden=true');t.runTimer(t.run('salvage.clock'));assert.equal(t.run('salvage.timeLeft'),44);});
test('border tactics opens at the top as a direct route and restores its lobby',t=>{t.run("ui.arcadeGamePages.scrollTop=651;window.NeonBorderTactics={enter:function(){window.borderEnterCount=(window.borderEnterCount||0)+1;},leave:function(){window.borderLeaveCount=(window.borderLeaveCount||0)+1;}};enterArcadeGame('border',false)");assert.equal(t.location.hash,'#game/border');assert.equal(t.run('ui.arcadeGamePages.scrollTop'),0);assert.equal(t.run("app.classList.contains('arcadeGameMode')"),true);assert.equal(t.run("ui.arcadeGamePages.classList.contains('hidden')"),false);assert.equal(t.run("ui.borderTacticsPage.classList.contains('hidden')"),false);assert.equal(t.run("ui.expeditionGamePage.classList.contains('hidden')"),true);assert.equal(t.run('window.borderEnterCount'),1);t.location.hash='#game/border';t.windowEvents.hashchange();assert.equal(t.run('ui.arcadeGamePages.scrollTop'),0);assert.equal(t.run('window.borderEnterCount'),2);});
test('dynamically rendered activity cards route to standalone games',t=>{const button={dataset:{hubView:'salvage'},hasAttribute:()=>false};t.events.click({target:{closest:()=>button}});assert.equal(t.location.hash,'#game/salvage');assert.equal(t.run("app.classList.contains('arcadeGameMode')"),true);assert.equal(t.run("ui.arcadeGamePages.classList.contains('hidden')"),false);});
test('contract actions route while incomplete and claim once complete',t=>{const open={dataset:{hubView:'lab',stationContract:'echo-research'},hasAttribute:()=>false};t.events.click({target:{closest:()=>open}});assert.equal(t.location.hash,'#game/lab');assert.equal(t.run("profile.station.claimed['echo-research']||false"),false);t.run('profile.relayHits=80');const claim={dataset:{hubView:'',stationContract:'relay-intel'},hasAttribute:()=>false};t.events.click({target:{closest:()=>claim}});assert.equal(t.run("profile.station.claimed['relay-intel']"),true);});
test('leaving a game clears every mode timer and cancels live combat',t=>{const result=JSON.parse(t.run("(function(){startRelay();startLab();startSalvage();startBlackbox();hintBlackbox();startGame();openArcadeLanding(true);return JSON.stringify({relay:relayRuntime.activeCount(),lab:labRuntime.activeCount(),salvage:salvageRuntime.activeCount(),blackbox:blackboxRuntime.activeCount(),running:g.running,frames:g.raf?1:0,hub:ui.hubOverlay.classList.contains('hidden'),pages:ui.arcadeGamePages.classList.contains('hidden'),landing:ui.arcadeLanding.classList.contains('hidden')});})()"));assert.equal(result.relay,0);assert.equal(result.lab,0);assert.equal(result.salvage,0);assert.equal(result.blackbox,0);assert.equal(result.running,false);assert.equal(t.frames.size,0);assert.equal(result.hub,true);assert.equal(result.pages,true);assert.equal(result.landing,false);});
test('chronicle preserves mode-specific goals and run choices',t=>{t.run("profile.history=[];pushChronicle({type:'salvage',contract:'data',contractClear:true,data:3,relics:1,ruleOrder:['forward','reverse','split','shift','extra'],upgrades:['wideband'],perks:['lens'],mastery:'oxygen'})");assert.equal(t.run("profile.history[0].contract"),'data');assert.equal(t.run('profile.history[0].contractClear'),true);assert.equal(t.run('profile.history[0].data'),3);assert.equal(t.run('profile.history[0].relics'),1);assert.equal(t.run('profile.history[0].ruleOrder.length'),4);assert.equal(t.run("profile.history[0].perks[0]"),'lens');assert.equal(t.run("profile.history[0].mastery"),'oxygen');});
test('border operation rewards, profile and chronicle settle once per operation id',t=>{const result=JSON.parse(t.run("(function(){var before=profile.shards,run={id:'ls-test-01',outcome:'clear',score:460,kills:5,sector:3,turns:12,seed:'LS07-TEST',contract:'猎杀指挥官',reward:{shards:9,intel:4,modules:2}},first=window.NeonProfileBridge.recordBorderRun(run),duplicate=window.NeonProfileBridge.recordBorderRun(run);return JSON.stringify({first:first,duplicate:duplicate,runs:profile.borderTactics.runs,clears:profile.borderTactics.clears,best:profile.borderTactics.bestScore,kills:profile.totalKills,shards:profile.shards-before,intel:profile.station.intel,modules:profile.station.modules,type:profile.history[0].type,operationId:profile.history[0].operationId});})()"));assert.equal(result.first,true);assert.equal(result.duplicate,false);assert.equal(result.runs,1);assert.equal(result.clears,1);assert.equal(result.best,460);assert.equal(result.kills,5);assert.equal(result.shards,9);assert.equal(result.intel,4);assert.equal(result.modules,2);assert.equal(result.type,'border');assert.equal(result.operationId,'ls-test-01');});
test('chronicle keeps bounded cross-mode history',t=>{t.run("profile.history=[];pushChronicle({type:'run',title:'远征结束',subtitle:'脉冲猎手 · 初始航道',score:88,wave:4,kills:19,shards:6});pushChronicle({type:'relay',title:'中继完成',subtitle:'NEON RELAY · 2 次命中',score:24,hits:2})");assert.equal(t.run('profile.history.length'),2);assert.equal(t.run("profile.history[0].type"),'relay');assert.equal(t.run("profile.history[1].wave"),4);t.run("for(var i=0;i<24;i++)pushChronicle({title:'旧记录',score:i})");assert.equal(t.run('profile.history.length'),18);});
test('keyboard movement and ability shortcuts work on desktop',t=>{const preventDefault=()=>{};const before=t.run('ship.x');t.windowEvents.keydown({code:'KeyD',key:'d',repeat:false,preventDefault});t.run('update(.1)');assert.ok(t.run('ship.x')>before);t.windowEvents.keyup({code:'KeyD',key:'d'});t.windowEvents.keydown({code:'Space',key:' ',repeat:false,preventDefault});assert.equal(t.run('g.dashCooldown'),4.5);t.windowEvents.keydown({code:'KeyE',key:'e',repeat:false,preventDefault});assert.ok(t.run('g.empCooldown')>0);});
test('inventory swaps preserve item count and slots',t=>{t.run("g.inventory.push(makeItem('arc'));equipInventory(0)");assert.equal(t.run('g.equipment.weapon.defId'),'arc');assert.equal(t.run('g.inventory.length'),1);});
test('loot replacement moves the displaced equipment into the backpack',t=>{t.run("equipNewItem(makeItem('phase'))");assert.equal(t.run('g.equipment.weapon.defId'),'phase');assert.equal(t.run('g.inventory.length'),1);assert.equal(t.run('g.inventory[0].defId'),'pulse');});
test('full backpack keeps old equipment and leaves the choice unresolved',t=>{t.run("g.inventory=Array.from({length:12},()=>makeItem('barrier'));g.choosing=true;g.pendingLoot=[makeItem('phase')];claimLoot(g.pendingLoot[0],'equip')");assert.equal(t.run('g.equipment.weapon.defId'),'pulse');assert.equal(t.run('g.inventory.length'),12);assert.equal(t.run('g.choosing'),true);});
test('upgrade chips strengthen gear only inside the paused armory',t=>{const before=t.run('estimatedDps()');t.run('g.upgradeKits=1;openArmory();upgradeEquipment(\'weapon\')');assert.equal(t.run('g.upgradeKits'),0);assert.equal(t.run('g.equipment.weapon.level'),2);assert.ok(t.run('estimatedDps()')>before);});
test('elite and boss rewards provide usable upgrade chips',t=>{t.run("g.upgradeKits=0;drops=[];dropAt(ship.x,ship.y,false,true);update(.016)");assert.equal(t.run('g.upgradeKits'),1);assert.equal(t.run('drops.length'),0);});
test('matrix station upgrade unlocks the sixth slot without resetting old gear',t=>{t.run("profile.activeLoadout={weapon:{defId:'pulse'},subweapon:{defId:'missile'},core:{defId:'nano'},utility:{defId:'emp'},engine:{defId:'drift'}};profile.station.modules=4;profile.station.upgrades.matrixBay=0;buyStationUpgrade('matrixBay')");assert.equal(t.run('profile.station.modules'),0);assert.equal(t.run("isSlotUnlocked('augment')"),true);assert.equal(t.run('g.equipment.weapon.defId'),'pulse');assert.equal(t.run('g.equipment.augment.defId'),'aegisMesh');assert.equal(t.run('buildItems().length'),6);});
test('locked matrix slot stays out of drops and serialized loadouts',t=>{t.run('profile.station.upgrades.matrixBay=0;resetRun()');assert.equal(t.run("isItemUnlocked(itemDefs.find(function(def){return def.slot==='augment';}))"),false);assert.equal(t.run("serializeLoadout(g.equipment).augment"),undefined);});
test('recalculation does not refill shield or EMP',t=>{t.run('ship.shield=0;traits.empCharges=0;recalcBuild()');assert.equal(t.run('ship.shield'),0);assert.equal(t.run('traits.empCharges'),0);});
test('missed player bullets are reclaimed',t=>{t.run("traits.auxMode='';ship.fireTimer=100;bullets.push({x:0,y:-100,vx:0,vy:-100,r:3,damage:1,hitIds:{},remainingPierce:0});update(.016)");assert.equal(t.run('bullets.length'),0);});
test('full bag cannot repeatedly farm loot scrap',t=>{t.run("g.inventory=Array.from({length:12},()=>makeItem('pulse'));g.levelQueue=1;openLoot();var chosen=g.pendingLoot[0];claimLoot(chosen,'bag');claimLoot(chosen,'bag')");assert.equal(t.run('g.scrap'),1);assert.equal(t.run('g.levelQueue'),0);});
test('full bag prevents losing equipped item',t=>{t.run("g.inventory=Array.from({length:12},()=>makeItem('pulse'));unequipSlot('weapon')");assert.equal(t.run('g.scrap'),0);assert.equal(t.run('g.equipment.weapon.defId'),'pulse');});
test('boss score awarded once',t=>{const score=t.run('g.wave=5;spawnBoss();g.boss.score');t.run('killEnemy(g.boss)');assert.equal(t.run('g.score'),score);});
test('modal open-close leaves one frame scheduled',t=>{t.run('openArmory();closeArmory()');assert.equal(t.frames.size,1);});
test('piercing projectile crosses targets once each',t=>{t.run("ship.fireTimer=100;enemies=[{uid:'a',x:100,y:150,r:8,hp:100,maxHp:100,shield:0,armor:0,vy:0,vx:0,phase:0,fire:100},{uid:'b',x:100,y:100,r:8,hp:100,maxHp:100,shield:0,armor:0,vy:0,vx:0,phase:0,fire:100}];bullets=[{x:100,y:200,vx:0,vy:-4000,r:3,damage:10,hitIds:{},remainingPierce:2}];update(.03)");assert.equal(t.run('enemies[0].hp'),90);assert.equal(t.run('enemies[1].hp'),90);});
test('all equipment definitions route to valid slots',t=>{
  assert.equal(t.run("profile.station.upgrades.matrixBay=1;resetRun();itemDefs.every(function(def){resetRun();return isSlotUnlocked(def.slot)&&equipNewItem(makeItem(def.id))&&g.equipment[def.slot].defId===def.id&&Object.keys(slotMeta).length===6;})"),true);
});
test('modal switching cannot resume behind another modal',t=>{t.run('openArmory();openArchive();togglePause()');assert.equal(t.run('g.paused'),true);assert.equal(t.frames.size,0);t.run('closeArchive()');assert.equal(t.frames.size,1);});
test('closing armory restores prior pause',t=>{t.run('togglePause();openArmory();closeArmory()');assert.equal(t.run('g.paused'),true);assert.equal(t.run("ui.pauseOverlay.classList.contains('hidden')"),false);assert.equal(t.frames.size,0);});
test('restart cancels previous animation and resets combat',t=>{t.run('ship.fireTimer=99;startGame()');assert.equal(t.frames.size,1);assert.equal(t.run('ship.fireTimer'),0);assert.equal(t.run('g.boss'),null);});
test('swarm boost expires',t=>{t.run("g.equipment.engine=makeItem('swarm');recalcBuild();ship.swarmTimer=.01;update(.02)");assert.equal(t.run('orbitalCount()'),0);});
test('duplicate equipment fuses instead of filling bag',t=>{t.run("equipNewItem(makeItem('pulse','rare'))");assert.equal(t.run('g.equipment.weapon.level'),2);assert.equal(t.run('g.equipment.weapon.rarity'),'rare');assert.equal(t.run('g.inventory.length'),0);});
test('max-level fusion upgrades rarity without false scrap',t=>{t.run("g.equipment.weapon.level=6;g.equipment.weapon.rarity='common';equipNewItem(makeItem('pulse','epic'))");assert.equal(t.run('g.equipment.weapon.rarity'),'epic');assert.equal(t.run('g.scrap'),0);});
test('new capacity grants only the added shield and EMP charge',t=>{
  t.run("g.equipment.utility=makeItem('gravity');recalcBuild(true);ship.shield=5;traits.empCharges=0;g.equipment.core=makeItem('barrier');g.equipment.utility=makeItem('emp');recalcBuild()");
  assert.ok(t.run('ship.shield')>5);assert.equal(t.run('traits.empCharges'),1);
});
test('defined loadout synergies activate mechanically',t=>{t.run("g.equipment.weapon=makeItem('phase');g.equipment.utility=makeItem('gravity');recalcBuild()");assert.ok(t.run("traits.synergies.includes('时滞穿刺')"));assert.ok(t.run('ship.pierce')>=3);});
test('wave transition waits for remaining enemies',t=>{t.run("g.waveKills=g.waveTarget;enemies=[{uid:'leftover',dead:false,boss:false}];advanceWave()");assert.equal(t.run('g.wave'),1);t.run('enemies=[];advanceWave()');assert.equal(t.run('g.wave'),2);});
test('loot reroll spends escalating scrap',t=>{t.run('g.scrap=10;g.levelQueue=1;openLoot();rerollLoot();rerollLoot()');assert.equal(t.run('g.scrap'),5);assert.equal(t.run('g.lootRerolls'),2);assert.equal(t.run('g.levelQueue'),1);});
test('loot salvage resolves exactly one queued level',t=>{t.run('g.levelQueue=2;openLoot();salvageLoot()');assert.equal(t.run('g.scrap'),2);assert.equal(t.run('g.levelQueue'),1);assert.equal(t.run('g.choosing'),true);});
test('returning from background resumes an open loot choice',t=>{t.run('g.levelQueue=1;openLoot()');t.document.hidden=true;t.events.visibilitychange();assert.equal(t.frames.size,0);t.document.hidden=false;t.events.visibilitychange();assert.equal(t.frames.size,1);assert.equal(t.run('g.choosing'),true);});
test('threat database includes regular enemies and bosses',t=>assert.equal(t.run('enemyOrder.length+bossDefs.length'),12));
test('every threat has a readable combat identity',t=>assert.equal(t.run("enemyOrder.every(function(id){var d=enemyDefs[id];return d.roleTag&&d.attackLabel&&d.readableCue;})&&bossDefs.every(function(d){return d.roleTag&&d.attackLabel&&d.readableCue;})"),true));
test('threat archive renders role and response guidance',t=>{assert.ok(t.run("threatMetaMarkup(enemyDefs.scout).includes('threatRole')"));assert.ok(t.run("threatMetaMarkup(enemyDefs.scout).includes('看到粉红环时横向移开')"));});
test('combat signatures cover every enemy family and boss',t=>assert.equal(t.run("enemyOrder.every(function(id){return !!enemyDefs[id].frame;})&&bossDefs.every(function(d){return d.frame.length===2;})"),true));
test('subweapon is independent from the main weapon and fires',t=>{const result=JSON.parse(t.run("(function(){resetRun();g.equipment.subweapon=makeItem('missile','rare');recalcBuild(true);traits.auxMode='missile';traits.auxDamage=20;ship.auxFireTimer=0;enemies=[{uid:'aux-target',x:180,y:120,dead:false,r:12}];shootAux();return JSON.stringify({main:g.equipment.weapon.defId,sub:g.equipment.subweapon.defId,missile:bullets.some(function(b){return b.aux&&b.auxSlow!==undefined;})});})()"));assert.equal(result.main,'pulse');assert.equal(result.sub,'missile');assert.equal(result.missile,true);});
test('unlocked subweapon blueprints enter the shared loot pool',t=>{t.run("profile.relayHits=24;syncBlueprintUnlocks(true)");assert.equal(t.run("hasBlueprint('relay-drone')"),true);assert.equal(t.run("isItemUnlocked(itemDefs.find(function(def){return def.id==='drone';}))"),true);assert.ok(t.run("rollLootChoices().some(function(item){return item.defId==='drone';})")||t.run("lootDefPool('subweapon',{}).some(function(def){return def.id==='drone';})"));});
test('new subweapon families produce distinct combat objects',t=>{const result=JSON.parse(t.run("(function(){var modes=['drone','beam','mineLauncher'],out={};modes.forEach(function(id){resetRun();g.equipment.subweapon=makeItem(id);recalcBuild(true);enemies=[{uid:'aux-'+id,x:180,y:120,dead:false,r:12,boss:false,type:'elite'}];bullets=[];mines=[];shootAux();out[id]={mode:traits.auxMode,bullets:bullets.filter(function(b){return b.aux;}).length,mines:mines.length};});return JSON.stringify(out);})()"));assert.equal(result.drone.mode,'drone');assert.ok(result.drone.bullets>=1);assert.equal(result.beam.mode,'beam');assert.ok(result.beam.bullets>=1);assert.equal(result.mineLauncher.mode,'mine');assert.equal(result.mineLauncher.mines,1);});
test('max-level duplicate weapon opens a branch and keeps the fusion upgrade',t=>{t.run("resetRun();g.equipment.weapon=makeItem('pulse','common');g.equipment.weapon.level=6;g.levelQueue=1;g.choosing=true;g.pendingLoot=[makeItem('pulse','rare')];claimLoot(g.pendingLoot[0],'equip');chooseWeaponBranch('guard')");assert.equal(t.run('g.equipment.weapon.level'),6);assert.equal(t.run('g.equipment.weapon.rarity'),'rare');assert.equal(t.run("g.equipment.weapon.branch"),'guard');assert.equal(t.run("traits.weaponBranchLabel"),'护航脉冲');});
test('weapon branch changes the real combat feedback',t=>{t.run("resetRun();g.equipment.weapon=makeItem('pulse');g.equipment.weapon.level=6;g.equipment.weapon.branch='guard';recalcBuild(true);ship.shield=0;killEnemy({uid:'branch-target',type:'scout',x:100,y:100,r:12,hp:0,maxHp:20,score:0,xp:0,typeColor:'#fff',bulletDamage:0,mutation:null,dead:false});");assert.ok(t.run('ship.shield>0'));assert.ok(t.run("traits.buildTagLabels.includes('护盾')"));});
test('duplicate loot fuses into the equipped build instead of stacking forever',t=>{t.run("g.inventory=[makeItem('pulse','common')];storeInventory(makeItem('pulse','rare'))");assert.equal(t.run('g.inventory.length'),1);assert.equal(t.run('g.equipment.weapon.level'),2);assert.equal(t.run("g.equipment.weapon.rarity"),'rare');});
test('short modes feed the shared star-dust economy',t=>{t.run("profile.shards=0;startRelay();relay.score=180;relay.hits=5;finishRelay();startLab();lab.score=220;lab.solved=4;finishLab('sequence')");assert.ok(t.run('profile.shards')>=4);assert.equal(t.run("profile.history[0].shards>0"),true);});
test('activity finishes feed the shared station economy',t=>{t.run("profile.station={intel:0,modules:0,research:0,claimed:{},upgrades:{navigator:0,moduleBay:0,echoDecoder:0}};startRelay();relay.score=180;relay.hits=50;finishRelay();startLab();lab.score=220;lab.solved=4;finishLab('sequence')");assert.equal(t.run('profile.station.intel'),2);assert.equal(t.run('profile.station.research'),2);});
test('station contracts can be completed and claimed once',t=>{t.run("profile.station={intel:0,modules:0,research:0,claimed:{},upgrades:{navigator:0,moduleBay:0,echoDecoder:0}};profile.relayHits=80;renderHubMissionBoard();claimStationContract('relay-intel');");assert.equal(t.run("profile.station.claimed['relay-intel']"),true);assert.equal(t.run('profile.station.intel'),4);assert.equal(t.run("claimStationContract('relay-intel')"),false);});
test('daily station directive migrates, rotates by date and caps progress',t=>{const result=JSON.parse(t.run("(function(){profile.dailyDirective={date:'',id:'',value:0,claimed:false};var first=ensureDailyDirective('2026-09-23'),id=profile.dailyDirective.id;var same=ensureDailyDirective('2026-09-23');var sameId=profile.dailyDirective.id,next=ensureDailyDirective('2026-09-24'),nextId=profile.dailyDirective.id;var def=dailyDirectiveById(nextId);profile.dailyDirective={date:'2026-09-24',id:def.id,value:0,claimed:false};ensureDailyDirective('2026-09-24');advanceDailyDirective(def.kind,def.target-1,'2026-09-24');var before=profile.dailyDirective.value;advanceDailyDirective(def.kind,99,'2026-09-24');return JSON.stringify({first:first,id:id,same:same,sameId:sameId,next:next,nextId:nextId,before:before,after:profile.dailyDirective.value,target:def.target});})()"));assert.equal(result.first,true);assert.equal(result.same,false);assert.equal(result.id,result.sameId);assert.equal(result.next,true);assert.notEqual(result.id,result.nextId);assert.equal(result.before,result.target-1);assert.equal(result.after,result.target);});
test('daily station directive rewards exactly once',t=>{const result=JSON.parse(t.run("(function(){var date='2026-09-23',def=dailyDirectiveForDate(date);profile.dailyDirective={date:date,id:def.id,value:def.target,claimed:false};profile.station={intel:0,modules:0,research:0,claimed:{},upgrades:{navigator:0,moduleBay:0,echoDecoder:0}};profile.shards=0;var first=claimDailyDirective(date),resources={intel:profile.station.intel,modules:profile.station.modules,research:profile.station.research,shards:profile.shards},second=claimDailyDirective(date);return JSON.stringify({first:first,second:second,claimed:profile.dailyDirective.claimed,resources:resources});})()"));assert.equal(result.first,true);assert.equal(result.second,false);assert.equal(result.claimed,true);assert.ok(result.resources.intel+result.resources.modules+result.resources.research+result.resources.shards>0);});
test('station upgrades spend resources and change the next run',t=>{t.run("profile.station={intel:4,modules:3,research:3,claimed:{},upgrades:{navigator:0,moduleBay:0,echoDecoder:0}};resetRun();buyStationUpgrade('moduleBay');buyStationUpgrade('navigator');buyStationUpgrade('echoDecoder')");assert.equal(t.run('inventoryCapacity()'),14);assert.equal(t.run('profile.station.modules'),0);assert.equal(t.run('profile.station.upgrades.navigator'),1);assert.equal(t.run('profile.station.upgrades.echoDecoder'),1);assert.ok(t.run('traits.empMax')>=2);});
test('station announcements open as a floating bulletin',t=>{t.run('openAnnouncement()');assert.equal(t.run("ui.announcementOverlay.classList.contains('hidden')"),false);assert.ok(t.run("ui.announcementHero.innerHTML.includes('V50 / BREACH PRESSURE')"));t.run('closeAnnouncement();setHubView(\'dispatch\')');assert.equal(t.run("ui.announcementOverlay.classList.contains('hidden')"),false);t.run('closeAnnouncement()');assert.equal(t.run("ui.announcementOverlay.classList.contains('hidden')"),true);});
test('loot choices never repeat an equipment definition',t=>assert.equal(t.run("(function(){var a=rollLootChoices().map(function(i){return i.defId;});return new Set(a).size===3;})()"),true));
test('loot choices cap main weapon duplicates',t=>assert.equal(t.run("(function(){for(var i=0;i<40;i++){var main=rollLootChoices(3).filter(function(item){return getDef(item).slot==='weapon';}).length;if(main>1)return false;}return true;})()"),true));
test('loot board keeps main weapons occasional and exposes subweapons',t=>{const result=JSON.parse(t.run("(function(){var main=0,sub=0;for(var i=0;i<80;i++){rollLootChoices().forEach(function(item){if(getDef(item).slot==='weapon')main++;if(getDef(item).slot==='subweapon')sub++;});}return JSON.stringify({main:main,sub:sub});})()"));assert.ok(result.main<80);assert.ok(result.sub>0);});
test('carrier enemy deploys two readable escorts below half hull',t=>{const result=JSON.parse(t.run("(function(){enemies=[];g.running=true;var e={uid:'carrier-test',type:'carrier',x:180,y:150,r:23,hp:40,maxHp:100,shield:0,maxShield:0,armor:0,vy:0,vx:50,phase:0,fire:100,score:0,xp:0,contact:0,bulletDamage:8,typeColor:'#75ffb2',mutation:null,summoned:false,deployed:false,dead:false,slowTimer:0,lastHit:0,flash:0,attackWarn:0,attackAngle:0,warnedFire:false,dashTimer:2,dashActive:0,dashWarning:0};enemies=[e];g.spawnTimer=100;update(.016);return JSON.stringify({deployed:e.deployed,escorts:enemies.filter(function(item){return item.summoned;}).length});})()"));assert.equal(result.deployed,true);assert.equal(result.escorts,2);});
test('weapon signatures are carried into player projectiles',t=>{const result=JSON.parse(t.run("(function(){resetRun();g.equipment.weapon=makeItem('phase');recalcBuild(true);bullets=[];ship.fireTimer=0;shoot();return JSON.stringify({mode:traits.weaponMode,kind:bullets[0].kind});})()"));assert.equal(result.mode,'phase');assert.equal(result.kind,'phase');});
test('boss phase transition creates readable feedback',t=>{t.run('g.wave=5;spawnBoss();var boss=g.boss;boss.y=boss.targetY;boss.hp=boss.maxHp*.6;updateBoss(boss,.016)');assert.equal(t.run('g.boss.phase'),2);assert.ok(t.run("damageTexts.some(function(item){return item.text==='PHASE 2';})"));});
test('opening loot releases an active drag',t=>{t.run('pointer=true;g.levelQueue=1;openLoot()');assert.equal(t.run('pointer'),false);});
test('phase dash moves, grants invulnerability and clears nearby bullets',t=>{
  const result=JSON.parse(t.run("(function(){ship.x=180;ship.y=430;ship.targetX=280;ship.targetY=430;enemyBullets=[{x:260,y:430,vx:0,vy:0,r:4,damage:9,life:8},{x:20,y:20,vx:0,vy:0,r:4,damage:9,life:8}];var used=useDash();return JSON.stringify({used:used,x:ship.x,invuln:ship.invuln,cooldown:g.dashCooldown,bullets:enemyBullets.length});})()"));
  assert.equal(result.used,true);assert.ok(result.x>180);assert.ok(result.invuln>=.6);assert.equal(result.cooldown,4.5);assert.equal(result.bullets,1);
});
test('phase dash cannot be reused during cooldown',t=>assert.equal(t.run("(function(){ship.targetX=300;ship.targetY=ship.y;useDash();var x=ship.x;useDash();return ship.x===x;})()"),true));
test('low frame rate catches up gameplay in safe substeps',t=>{
  const remaining=t.run('g.dashCooldown=4.5;g.last=0;loop(100);g.dashCooldown');
  assert.ok(remaining<4.405&&remaining>4.39);
});
test('every item produces finite combat stats',t=>assert.equal(t.run("itemDefs.every(function(def){resetRun();g.equipment[def.slot]=makeItem(def.id,'legendary');recalcBuild();return ['damage','fireRate','shots','pierce','maxHp','shield','crit','bulletSpeed','moveLerp'].every(function(k){return Number.isFinite(ship[k]);});})"),true));
test('every equipment definition has a distinct icon cell',t=>assert.equal(t.run("new Set(itemDefs.map(function(def){return def.frame?'frame:'+def.frame.join(','):'glyph:'+def.glyph;})).size"),t.run('itemDefs.length')));
test('atlas inline styles do not break their HTML attributes',t=>assert.equal(t.run("(function(){var item=makeItem('pulse');return !/[\"']/.test(iconStyle(item))&&!/[\"']/.test(enemyStyle(enemyDefs.scout))&&!/[\"']/.test(bossStyle(bossDefs[0]));})()"),true));
test('every boss phase can execute its attack pattern',t=>assert.equal(t.run("bossDefs.every(function(def){enemyBullets=[];lasers=[];var e={x:W/2,y:80,phase:3,bossId:def.id,typeColor:def.color};bossAttack(e);return enemyBullets.length+lasers.length>0;})"),true));
test('bosses rotate distinct phase patterns and use their warned aim angle',t=>{assert.equal(t.run("bossDefs.every(function(def){enemyBullets=[];lasers=[];var e={x:W/2,y:80,phase:2,bossId:def.id,typeColor:def.color,attackIndex:0,attackAngle:Math.PI};var seen=[];for(var i=0;i<3;i++){e.attackPattern=bossPatternAt(e,e.attackIndex);bossAttack(e);seen.push(e.lastAttackPattern);}return new Set(seen).size===3;})"),true);assert.equal(t.run("(function(){enemyBullets=[];var e={x:W/2,y:80,phase:1,bossId:'prism',typeColor:'#72f4ff',attackPattern:'fan',attackAngle:Math.PI};bossAttack(e);return enemyBullets.every(function(b){return b.vx<0;});})()"),true);});
test('early waves prioritize scouts and lengthen firing gaps',t=>{const result=JSON.parse(t.run("(function(){g.wave=2;updateWaveMod();var types=[];for(var i=0;i<600;i++)types.push(pickEnemyType(i/600,false));var shooters=types.filter(function(type){return type!=='scout';}).length;var wave2=g.waveMod.name;var interval=enemyShotInterval('zigzag');g.wave=3;updateWaveMod();var wave3shooters=0;for(var j=0;j<800;j++)if(pickEnemyType(j/800,false)!=='scout')wave3shooters++;return JSON.stringify({shooters:shooters/600,wave2:wave2,interval:interval,wave3shooters:wave3shooters/800});})()"));assert.ok(result.shooters<=.18);assert.equal(result.wave2,'相位装甲');assert.ok(result.interval>1.8);assert.ok(result.wave3shooters<=.4);});
test('prism boss summons escorts once per phase rather than once per attack',t=>assert.equal(t.run("(function(){g.wave=5;g.waveMod=waveMods[0];g.routeMod={fire:1};g.nodeMod={fire:1};enemies=[];var e={boss:true,bossId:'prism',x:W/2,y:100,targetY:100,r:52,hp:60,maxHp:100,shield:1,maxShield:1,shieldTimer:10,shieldRegen:0,phase:1,angle:0,slowTimer:0,lastHit:0,attackTimer:99,attackWarn:0,warnedAttack:false,attackIndex:0,summonedPhase:0,typeColor:'#72f4ff'};g.boss=e;enemies.push(e);updateBoss(e,.016);var first=enemies.length;updateBoss(e,.016);return first===2&&enemies.length===first;})()"),true));
test('hostile projectile population is capped',t=>{t.run("for(var i=0;i<900;i++)spawnProjectile(0,0,0,1,1)");assert.equal(t.run('enemyBullets.length'),700);});
test('boss shield break creates a real damage window',t=>{t.run('g.wave=5;spawnBoss();g.boss.y=g.boss.targetY;g.boss.shield=1;damageEnemy(g.boss,2,{})');assert.equal(t.run('g.boss.shield'),0);t.run('updateBoss(g.boss,5)');assert.equal(t.run('g.boss.shield'),0);t.run('updateBoss(g.boss,.3)');assert.ok(t.run('g.boss.shield')>0);});
test('combat telegraphs and damage feedback expose the next threat',t=>{const result=JSON.parse(t.run("(function(){resetRun();g.running=true;var e={uid:'warning',type:'artillery',x:90,y:100,r:18,hp:100,maxHp:100,shield:0,armor:0,vy:0,vx:0,phase:0,fire:.4,score:0,xp:0,contact:0,bulletDamage:8,typeColor:'#ff718e',mutation:null,dead:false,slowTimer:0,lastHit:0,flash:0,attackWarn:0,attackAngle:0,warnedFire:false,dashTimer:2,dashActive:0,dashWarning:0};enemies=[e];g.spawnTimer=100;update(.016);var warning=e.attackWarn>0;damageEnemy(e,10,{hitCritical:true});var hit=damageTexts.some(function(item){return item.critical;});ship.shield=0;damageShip(5);return JSON.stringify({warning:warning,hit:hit,shipShake:screenFx.shake>0});})()"));assert.equal(result.warning,true);assert.equal(result.hit,true);assert.equal(result.shipShake,true);});
test('boss warning marks the attack window before firing',t=>{t.run('resetRun();g.running=true;g.wave=5;spawnBoss();g.boss.y=g.boss.targetY;g.boss.attackTimer=.6;updateBoss(g.boss,.016)');assert.ok(t.run('g.boss.attackWarn>0'));assert.equal(t.run('g.boss.warnedAttack'),true);});
test('starter build can defeat first boss when tracking it',t=>assert.equal(t.run("(function(){g.wave=5;spawnBoss();for(var i=0;i<10800&&g.boss;i++){ship.invuln=1;ship.targetX=g.boss.x;update(1/60);if(g.choosing)salvageLoot();}return g.boss===null;})()"),true));
test('every wave modifier spawns finite enemy stats',t=>assert.equal(t.run("waveMods.every(function(mod){g.wave=15;g.waveMod=mod;spawnEnemy();var e=enemies.pop();return ['hp','vy','armor','shield','contact','bulletDamage'].every(function(k){return Number.isFinite(e[k]);});})"),true));
test('late-wave pool retains every regular enemy family',t=>assert.equal(t.run("(function(){g.wave=15;var seen={};for(var i=0;i<800;i++)seen[pickEnemyType(i/800,false)]=true;return enemyOrder.filter(function(x){return x!=='elite';}).every(function(x){return seen[x];});})()"),true));
test('late enemies resist one-shot builds and deal relevant damage',t=>assert.equal(t.run("(function(){g.equipment.weapon=makeItem('phase','legendary');g.equipment.weapon.level=6;recalcBuild();g.wave=20;g.waveMod=waveMods[0];var old=Math.random;Math.random=function(){return 0;};spawnEnemy();Math.random=old;var e=enemies.pop();return e.hp>ship.damage*ship.critMult&&e.bulletDamage>baseStats.maxHp*.25;})()"),true));
test('enemy mutations begin at wave four and attach to spawned enemies',t=>assert.equal(t.run("(function(){g.wave=4;updateWaveMod();var old=Math.random;Math.random=function(){return .1;};spawnEnemy();Math.random=old;return g.mutation.id==='berserk'&&enemies[0].mutation.id==='berserk';})()"),true));
test('revenge mutation releases a bounded death burst',t=>{t.run("enemyBullets=[];killEnemy({uid:'mutant',type:'gunner',x:120,y:120,r:18,hp:0,maxHp:50,score:0,xp:0,typeColor:'#fff',bulletDamage:20,mutation:enemyMutations[1],dead:false})");assert.equal(t.run('enemyBullets.length'),8);});
test('split mutation creates exactly two non-recursive shards',t=>{t.run("enemies=[];killEnemy({uid:'splitter',type:'tank',x:120,y:120,r:20,hp:0,maxHp:50,score:0,xp:0,typeColor:'#fff',bulletDamage:20,mutation:enemyMutations[2],summoned:false,dead:false})");assert.equal(t.run("enemies.filter(function(e){return e.summoned;}).length"),2);assert.equal(t.run("enemies.every(function(e){return e.mutation===null;})"),true);});
test('jammer mutation slows weapon cadence only while nearby',t=>{const normal=t.run('ship.fireTimer=0;ship.jammed=false;shoot();ship.fireTimer');const jammed=t.run('ship.fireTimer=0;ship.jammed=true;shoot();ship.fireTimer');assert.ok(jammed>normal*1.3);});
test('boss defeat grants scrap and an epic-or-better cache',t=>assert.equal(t.run("(function(){g.wave=5;spawnBoss();g.boss.xp=0;killEnemy(g.boss);return g.scrap===3&&g.pendingLootFloor==='epic'&&g.pendingLoot.every(function(i){return rarityRank(i.rarity)>=rarityRank('epic');});})()"),true));
test('completed mission refreshes after two waves',t=>assert.equal(t.run("(function(){g.missionTarget=1;g.missionReward=900;killEnemy({uid:'mission',type:'scout',x:100,y:100,r:12,hp:0,maxHp:20,score:0,xp:0,typeColor:'#fff',bulletDamage:0,mutation:null,dead:false});var due=g.nextMissionWave;g.wave=due;updateWaveMod();return !g.missionDone&&g.missionKills===0&&g.missionTarget>1&&g.scrap===2;})()"),true));
test('five simulated minutes have bounded bullets and finite state',t=>{
  const state=JSON.parse(t.run("(function(){var valid=true;for(var i=0;i<18000;i++){ship.invuln=1;ship.targetX=W/2+Math.sin(i*.009)*100;update(1/60);if(g.choosing)claimLoot(g.pendingLoot[0],'bag');if(!Number.isFinite(ship.hp)||!Number.isFinite(ship.x)||bullets.length>200||enemyBullets.length>1000){valid=false;break;}}return JSON.stringify({valid:valid,wave:g.wave,kills:g.kills,level:g.level,enemies:enemies.length,bullets:bullets.length,enemyBullets:enemyBullets.length});})()"));
  assert.equal(state.valid,true);assert.ok(state.wave>=3);if(process.env.DIAGNOSTIC)console.log('SIMULATION',state);
});
test('loot freezes cooldowns and collision damage',t=>{
 t.run('g.dashCooldown=3;g.levelQueue=1;openLoot();ship.hp=80;ship.shield=0;update(.1);damageShip(30)');
 assert.equal(t.run('ship.hp'),80);assert.equal(t.run('g.dashCooldown'),3);
});
test('upgrade triggered during catch-up stops the next substep',t=>{
 t.run("ship.x=180;ship.y=430;ship.targetX=180;ship.targetY=430;ship.fireTimer=100;g.spawnTimer=100;g.xp=79;spawnEnemy();var e=enemies[0];Object.assign(e,{x:100,y:100,hp:1,shield:0,armor:0,xp:2,vy:0});bullets=[{x:100,y:110,vx:0,vy:-900,r:3,damage:99,hitIds:{},remainingPierce:0}];g.last=0;loop(100)");
 assert.equal(t.run('g.choosing'),true);assert.ok(t.run('g.elapsed')<.02);assert.equal(t.run('g.accumulator'),0);
});
test('long browser stalls pause without advancing combat',t=>{
 t.run('g.last=0;g.dashCooldown=3;loop(900)');assert.equal(t.run('g.paused'),true);assert.equal(t.run('g.dashCooldown'),3);assert.equal(t.run('g.elapsed'),0);
});
test('drift overload changes actual weapon interval',t=>{const normal=t.run('ship.driftTimer=0;fireInterval()');const boosted=t.run('ship.driftTimer=1.2;fireInterval()');assert.ok(boosted<normal*.8);});
test('checking equipped details does not unequip',t=>{t.run("renderEquipmentDetail('weapon')");assert.equal(t.run('g.equipment.weapon.defId'),'pulse');assert.equal(t.run('g.inventory.length'),0);});
test('comparison does not heal or refill charges',t=>{t.run("ship.hp=30;ship.shield=0;traits.empCharges=0;compareEquipment(makeItem('barrier'))");assert.equal(t.run('ship.hp'),30);assert.equal(t.run('ship.shield'),0);assert.equal(t.run('traits.empCharges'),0);});
test('stale inventory index cannot grant scrap',t=>{t.run('scrapInventory(500)');assert.equal(t.run('g.scrap'),0);});
test('second touch cannot hijack movement or cancel the first touch',t=>{
 const n=t.nodes.get('gameCanvas');n.listeners.pointerdown({pointerId:1,clientX:100,clientY:400,pointerType:'touch'});
 n.listeners.pointerdown({pointerId:2,clientX:300,clientY:400,pointerType:'touch'});n.listeners.pointerup({pointerId:2});
 n.listeners.pointermove({pointerId:1,clientX:120,clientY:400,pointerType:'touch'});assert.equal(t.run('ship.targetX'),120);assert.equal(t.run('pointer'),true);
 n.listeners.lostpointercapture({pointerId:1});assert.equal(t.run('pointer'),false);
});
test('zero-score defeat is not a new record',t=>{t.run('endGame()');assert.equal(t.run('ui.resultTitle.textContent'),'战机损毁');assert.equal(t.run('ui.dashBtn.disabled'),true);});
test('re-equipping barrier and EMP cannot manufacture supplies',t=>{
  t.run("equipNewItem(makeItem('barrier'));ship.shield=0;traits.empCharges=0;for(var cycle=0;cycle<5;cycle++){unequipSlot('core');equipInventory(g.inventory.findIndex(function(i){return i.defId==='barrier';}));unequipSlot('utility');equipInventory(g.inventory.findIndex(function(i){return i.defId==='emp';}));}");
  assert.equal(t.run('ship.shield'),0);assert.equal(t.run('traits.empCharges'),0);
});
test('loot disables blocked navigation and restores it on claim',t=>{
  t.run('g.levelQueue=1;openLoot()');
  for(const id of ['pauseBtn','armoryBtn','archiveBtn'])assert.equal(t.nodes.get(id).disabled,true,id);
  t.run("claimLoot(g.pendingLoot[0],'bag')");
  for(const id of ['pauseBtn','armoryBtn','archiveBtn'])assert.equal(t.nodes.get(id).disabled,false,id);
});
